create or replace function kaoid_private.company_owner_authority() returns boolean language plpgsql stable security definer set search_path='' as $$ declare u uuid := auth.uid(); begin if u is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then return false; end if; if not exists(select 1 from public.profiles p where p.id=u and p.account_status='active' and p.deleted_at is null) then return false; end if; if exists(select 1 from public.company_owners o where o.profile_id=u) then return true; end if; return exists(select 1 from public.owner_delegations d join public.verifications v on v.profile_id=d.delegate_profile_id and v.status='approved' join public.kao_id_identities k on k.profile_id=d.delegate_profile_id and k.status='active' where d.delegate_profile_id=u and d.revoked_at is null and d.starts_at<=now() and d.expires_at>=now()); end $$; revoke all on function kaoid_private.company_owner_authority() from public,anon; grant execute on function kaoid_private.company_owner_authority() to authenticated; create or replace function public.is_company_owner() returns boolean language sql stable security invoker set search_path='' as $$ select kaoid_private.company_owner_authority(); $$; revoke all on function public.is_company_owner() from public,anon; grant execute on function public.is_company_owner() to authenticated;;
